                    <h2 id="staff-logbook-PATCHapi-v1-logbooks--logbook_id-">Update logbook time fields (DRAFT status only)</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Per plan spec section 9.2: PATCH /logbooks/{id}
Allows updating tanggal, start_kerja, end_kerja for DRAFT logbooks.</p>

<span id="example-requests-PATCHapi-v1-logbooks--logbook_id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost:8000/api/v1/logbooks/architecto" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"tanggal\": \"2026-03-19T23:01:37\",
    \"start_kerja\": \"23:01\",
    \"end_kerja\": \"23:01\",
    \"lokasi\": \"b\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/logbooks/architecto"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "tanggal": "2026-03-19T23:01:37",
    "start_kerja": "23:01",
    "end_kerja": "23:01",
    "lokasi": "b"
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

